declare(strict_types=1);use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$pending=$_SESSION['pending_saml']??null;if(!is_array($pending)||time()-(int)($pending['created_at']??0)>600){unset($_SESSION['pending_saml']);http_response_code(400);Web::page('SAML','<section class="card narrow"><h1>Żądanie SAML wygasło</h1></section>',$user);}try{$req=$pending['request'];$response=$saml->response($req,(int)$user['id'],$auth->authenticationContext());$relay=(string)($pending['relay_state']??'');unset($_SESSION['pending_saml']);$acs=(string)$req['acs'];$html='<!doctype html><html><body><form id="saml" method="post" action="'.Web::e($acs).'"><input type="hidden" name="SAMLResponse" value="'.Web::e($response).'">'.($relay!==''?'<input type="hidden" name="RelayState" value="'.Web::e($relay).'">':'').'</form><script>document.getElementById("saml").submit();</script><noscript><button form="saml">Kontynuuj</button></noscript></body></html>';header('Content-Type: text/html; charset=utf-8');header('Cache-Control: no-store');echo$html;exit;}catch(Throwable $e){unset($_SESSION['pending_saml']);http_response_code(403);Web::page('SAML','<section class="card narrow"><h1>Brak dostępu</h1><div class="code">'.Web::e($e->getMessage()).'</div></section>',$user);}
